#!/usr/bin/env python3
"""Build a standalone offline movement prototype using actual map and Sun Wukong assets."""
import base64,json,mimetypes
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
B=ROOT/'build'
maps=json.loads((B/'analysis/map-index.json').read_text(encoding='utf-8'))
act_all=json.loads((B/'analysis/act-index.json').read_text(encoding='utf-8'))
act=next(a for a in act_all if a['file']=='sunwk.act')
images={}
for name in sorted({m['tileset'] for m in maps}):
 p=B/'assets/map'/name; raw=p.read_bytes(); images['map:'+name]='data:image/png;base64,'+base64.b64encode(raw).decode()
for name in act['imageFiles']:
 p=B/'assets/sprite'/name; raw=p.read_bytes(); images['sprite:'+name]='data:image/png;base64,'+base64.b64encode(raw).decode()
html=r'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tây Du Chiến Ký — Asset Runtime Prototype</title>
<style>:root{color-scheme:dark;--bg:#0b1118;--panel:#151e29;--line:#304053;--text:#e7edf5;--muted:#9caec3;--gold:#e8bb62}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 Segoe UI,Arial,sans-serif}header{padding:16px 20px;background:#111a26;border-bottom:1px solid var(--line)}h1{font-size:19px;margin:0 0 3px}header p{margin:0;color:var(--muted)}main{display:flex;gap:14px;padding:14px;align-items:flex-start;flex-wrap:wrap}.game{background:#070c12;border:1px solid var(--line);border-radius:9px;padding:12px;max-width:100%;overflow:auto}canvas{display:block;width:960px;height:720px;max-width:none;image-rendering:pixelated;image-rendering:crisp-edges;background:#101820;border:1px solid #45556b}.side{width:310px;max-width:100%;padding:14px;background:var(--panel);border:1px solid var(--line);border-radius:9px}.bar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:10px}.bar label{color:var(--muted)}select,button{background:#0d1520;color:var(--text);border:1px solid #3a4b60;border-radius:6px;padding:7px 9px}button{cursor:pointer}.stats{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:10px 0}.stat{padding:8px;background:#0e1621;border:1px solid var(--line);border-radius:7px}.stat b{display:block;font-size:17px}.stat small{color:var(--muted)}.note{margin:0 14px 14px;padding:10px 12px;color:var(--muted);background:var(--panel);border:1px solid var(--line);border-radius:8px}kbd{padding:2px 5px;border:1px solid #506078;border-radius:4px;background:#101925;color:white}#status{color:var(--gold);margin:10px 0}
</style></head><body><header><h1>Tây Du Chiến Ký — Runtime Prototype</h1><p>Dựng cảnh 2D từ tileset, map data và sprite ACT gốc được trích xuất từ JAR.</p></header>
<main><section class="game"><div class="bar"><label for="mapSelect">Bản đồ</label><select id="mapSelect"></select><button id="markers">Ẩn đối tượng</button><label for="scale">Kích thước</label><select id="scale"><option value="2">2×</option><option value="3" selected>3×</option><option value="4">4×</option></select></div><canvas id="screen" width="320" height="240"></canvas></section>
<aside class="side"><h2 style="margin:0 0 8px;color:var(--gold)">Thông tin chạy thử</h2><div class="stats" id="stats"></div><div id="status">Đang tải tài nguyên...</div><p><b>Điều khiển thử:</b><br><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> hoặc các phím mũi tên để di chuyển.</p><p><b>Đã dùng dữ liệu gốc:</b><br>Tileset và tile index từ `.map`; tọa độ đối tượng từ `.map`; các rectangle, offset và animation group của Tôn Ngộ Không từ `sunwk.act`.</p><p><b>Chưa khôi phục:</b><br>Va chạm, trọng lực/vật lý gốc, AI quái, sát thương, kỹ năng, nhiệm vụ và luồng script. Nhân vật hiện có thể đi tự do trong giới hạn bản đồ.</p></aside></main>
<div class="note">Đây là bản dựng runtime đầu tiên từ asset thật, không phải bản clone hoàn chỉnh. Tốc độ/phản hồi điều khiển là tạm thời để kiểm tra việc ghép map và sprite. Không có dữ liệu nào được gửi ra Internet; file hoạt động độc lập khi mở trên Chrome/Edge.</div>
<script>
const MAPS=__MAPS__,ACT=__ACT__,IMAGES=__IMAGES__,SCREEN_W=320,SCREEN_H=240,TILE=32;
const $=id=>document.getElementById(id),canvas=$('screen'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const imageCache={};function img(k){if(!imageCache[k]){imageCache[k]=new Image();imageCache[k].src=IMAGES[k];imageCache[k].onload=()=>draw()}return imageCache[k]}
let map=null,camX=0,camY=0,showMarkers=true,scale=3,last=0,animElapsed=0,animFrame=0,moving=false;
const player={x:120,y:220,speed:2.4,face:1};const keys=new Set();
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
function mapById(id){return MAPS.find(m=>m.id===id)}
function transformTile(x,y,t){ctx.translate(x+16,y+16);switch(t){case 1:ctx.scale(1,-1);break;case 2:ctx.scale(-1,1);break;case 3:ctx.rotate(Math.PI);break;case 4:ctx.rotate(Math.PI/2);ctx.scale(1,-1);break;case 5:ctx.rotate(Math.PI/2);break;case 6:ctx.rotate(-Math.PI/2);break;case 7:ctx.rotate(-Math.PI/2);ctx.scale(1,-1);break}}
function drawTiles(){const im=img('map:'+map.tileset);if(!im.complete||!im.naturalWidth)return;const cols=im.width/TILE;const c0=Math.max(0,Math.floor(camX/TILE)),c1=Math.min(map.columns-1,Math.ceil((camX+SCREEN_W)/TILE));const r0=Math.max(0,Math.floor(camY/TILE)),r1=Math.min(map.rows-1,Math.ceil((camY+SCREEN_H)/TILE));
 for(let r=r0;r<=r1;r++)for(let c=c0;c<=c1;c++){const v=map.layer1[r][c];if(!v)continue;const id=Math.abs(v)-1,sx=(id%cols)*TILE,sy=Math.floor(id/cols)*TILE,dx=c*TILE-camX,dy=r*TILE-camY,t=map.layer2[r][c]||0;ctx.save();transformTile(dx,dy,t);ctx.drawImage(im,sx,sy,TILE,TILE,-16,-16,TILE,TILE);ctx.restore()}}
function drawMarkers(){if(!showMarkers)return;for(const o of map.objects){const x=o.x-camX,y=o.y-camY;if(x<-10||x>SCREEN_W+10||y<-10||y>SCREEN_H+10)continue;ctx.fillStyle=o.descriptor.startsWith('名称+')?'#e7b857':'#62d1df';ctx.strokeStyle='#101820';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,3.5,0,Math.PI*2);ctx.fill();ctx.stroke()}}
function drawSprite(){const seq=ACT.sequences[moving?1:0]||[];let gid=moving?seq[animFrame%Math.max(1,seq.length)]:(seq[0]??8);const g=ACT.animations[gid];if(!g)return;ctx.save();ctx.translate(Math.round(player.x-camX),Math.round(player.y-camY));ctx.scale(player.face,1);
 for(const f of g.frames){const r=ACT.rectangles[f[0]];if(!r)continue;const [sx,sy,w,h]=r,atlasIndex=r.length>4?r[4]:0,name=ACT.imageFiles[atlasIndex];if(!name)continue;const im=img('sprite:'+name);if(!im.complete||!im.naturalWidth)continue;ctx.save();ctx.translate(f[1]+w/2,f[2]+h/2);const t=f[3]||0;switch(t){case 1:ctx.scale(1,-1);break;case 2:ctx.scale(-1,1);break;case 3:ctx.rotate(Math.PI);break;case 4:ctx.rotate(Math.PI/2);ctx.scale(1,-1);break;case 5:ctx.rotate(Math.PI/2);break;case 6:ctx.rotate(-Math.PI/2);break;case 7:ctx.rotate(-Math.PI/2);ctx.scale(1,-1);break;}ctx.drawImage(im,sx,sy,w,h,-w/2,-h/2,w,h);ctx.restore()}
 ctx.restore()}
function draw(){if(!map)return;ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,SCREEN_W,SCREEN_H);ctx.fillStyle='#101820';ctx.fillRect(0,0,SCREEN_W,SCREEN_H);drawTiles();drawMarkers();drawSprite();}
function loadMap(id){map=mapById(id);if(!map)return;player.x=Math.min(120,map.worldWidth-32);player.y=Math.min(220,map.worldHeight-40);camX=camY=0;img('map:'+map.tileset);$('stats').innerHTML=`<div class="stat"><b>${map.worldWidth}×${map.worldHeight}</b><small>Kích thước map</small></div><div class="stat"><b>${map.objects.length}</b><small>Object descriptors</small></div><div class="stat"><b>${map.tileset}</b><small>Tileset</small></div><div class="stat"><b>${map.rows}×${map.columns}</b><small>Tile grid</small></div>`;$('status').textContent=`Map ${map.id} · Nhân vật: (${Math.round(player.x)}, ${Math.round(player.y)})`;draw()}
function update(now){const dt=Math.min(40,now-last||16);last=now;let dx=0,dy=0;if(keys.has('ArrowLeft')||keys.has('a')||keys.has('A'))dx--;if(keys.has('ArrowRight')||keys.has('d')||keys.has('D'))dx++;if(keys.has('ArrowUp')||keys.has('w')||keys.has('W'))dy--;if(keys.has('ArrowDown')||keys.has('s')||keys.has('S'))dy++;
 moving=!!(dx||dy);if(dx&&dy){dx*=.7071;dy*=.7071}if(dx)player.face=dx<0?-1:1;const speed=player.speed*dt/16.667;player.x=clamp(player.x+dx*speed,20,map.worldWidth-20);player.y=clamp(player.y+dy*speed,60,map.worldHeight-4);
 animElapsed+=dt;const delay=moving?105:240;if(animElapsed>=delay){animElapsed=0;animFrame++}camX=clamp(player.x-SCREEN_W/2,0,Math.max(0,map.worldWidth-SCREEN_W));camY=clamp(player.y-SCREEN_H*0.58,0,Math.max(0,map.worldHeight-SCREEN_H));$('status').textContent=`Map ${map.id} · Vị trí: (${Math.round(player.x)}, ${Math.round(player.y)}) · Animation group: ${moving?(ACT.sequences[1][animFrame%ACT.sequences[1].length]):(ACT.sequences[0][0]??8)}`;draw();requestAnimationFrame(update)}
MAPS.sort((a,b)=>Number(a.id)-Number(b.id));MAPS.forEach(m=>{const o=document.createElement('option');o.value=m.id;o.textContent=`${m.id} — ${m.tileset} — ${m.worldWidth}×${m.worldHeight}`;$('mapSelect').appendChild(o)});
$('mapSelect').value='101';loadMap('101');$('mapSelect').addEventListener('change',e=>loadMap(e.target.value));$('markers').addEventListener('click',()=>{showMarkers=!showMarkers;$('markers').textContent=showMarkers?'Ẩn đối tượng':'Hiện đối tượng';draw()});$('scale').addEventListener('change',e=>{scale=Number(e.target.value);canvas.style.width=(SCREEN_W*scale)+'px';canvas.style.height=(SCREEN_H*scale)+'px'});canvas.style.width='960px';canvas.style.height='720px';
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(e.key))e.preventDefault();keys.add(e.key)});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());
for(const name of ACT.imageFiles)img('sprite:'+name);requestAnimationFrame(update);
</script></body></html>'''
html=html.replace('__MAPS__',json.dumps(maps,ensure_ascii=False,separators=(',',':')))
html=html.replace('__ACT__',json.dumps(act,ensure_ascii=False,separators=(',',':')))
html=html.replace('__IMAGES__',json.dumps(images,separators=(',',':')))
out=ROOT/'game-prototype.html';out.write_text(html,encoding='utf-8')
print(f'Wrote {out} ({out.stat().st_size:,} bytes), {len(maps)} maps, Wukong ACT with {act["animationCount"]} groups')
